[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ShiftWise — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  --primary: #0051C3;
  --primary-dark: #0041A3;
  --accent: #DE5052;
  --accent-dark: #C03E3F;
  --white: #FFFFFF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
  --radius: 8px;
  --radius-lg: 12px;
  --transition: 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--primary-dark);
}

img {
  max-width: 100%;
  height: auto;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--accent-dark);
  color: var(--white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--white);
  color: var(--gray-800);
  border: 2px solid var(--gray-200);
}

.btn-secondary:hover {
  border-color: var(--gray-300);
  color: var(--gray-900);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

/* Header & Navigation */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
  z-index: 1000;
  padding: 0 24px;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
}

.nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  color: var(--gray-600);
  font-weight: 500;
  font-size: 0.95rem;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}

.nav-cta .btn {
  padding: 10px 20px;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--gray-700);
  margin: 5px 0;
  transition: var(--transition);
}

/* Mobile Navigation */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  padding: 24px;
  z-index: 999;
}

.mobile-nav.active {
  display: block;
}

.mobile-nav-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.mobile-nav-links a {
  display: block;
  padding: 12px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-nav-cta {
  margin-top: 24px;
}

.mobile-nav-cta .btn {
  width: 100%;
}

/* Hero Section */
.hero {
  padding: 160px 0 80px;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-500);
  margin-bottom: 40px;
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Page Hero (inner pages) */
.page-hero {
  padding: 140px 0 60px;
  background: var(--gray-50);
  text-align: center;
}

.page-hero h1 {
  margin-bottom: 16px;
}

.page-hero p {
  font-size: 1.125rem;
  color: var(--gray-500);
  max-width: 600px;
  margin: 0 auto;
}

/* Sections */
.section {
  padding: 80px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 60px;
}

.section-header p {
  color: var(--gray-500);
  margin-top: 16px;
  font-size: 1.125rem;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.feature-card:hover {
  border-color: var(--gray-200);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--gray-500);
  line-height: 1.7;
}

/* How It Works */
.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 40px;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 auto 20px;
}

.step h3 {
  margin-bottom: 12px;
}

.step p {
  color: var(--gray-500);
}

/* Testimonials */
.testimonials-wrapper {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-carousel {
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 48px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  color: var(--gray-700);
  line-height: 1.8;
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-author {
  font-weight: 600;
  color: var(--gray-900);
}

.testimonial-role {
  color: var(--gray-500);
  font-size: 0.95rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  font-size: 1.25rem;
  color: var(--gray-600);
  transition: var(--transition);
}

.testimonial-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.testimonial-dot.active {
  background: var(--primary);
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  text-align: center;
}

.stat-item h2 {
  font-size: 3rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-500);
  font-size: 1.05rem;
}

/* Pricing Table */
.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  margin-bottom: 48px;
}

.toggle-label {
  font-weight: 500;
  color: var(--gray-500);
}

.toggle-label.active {
  color: var(--gray-900);
}

.toggle-switch {
  width: 56px;
  height: 28px;
  background: var(--gray-200);
  border-radius: 14px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: var(--transition);
}

.toggle-switch.active::after {
  left: 31px;
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  text-align: center;
  transition: var(--transition);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 16px;
  border-radius: 20px;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 8px;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-card .price-desc {
  color: var(--gray-500);
  font-size: 0.95rem;
  margin-bottom: 24px;
}

.pricing-features {
  list-style: none;
  text-align: left;
  margin: 24px 0;
}

.pricing-features li {
  padding: 10px 0;
  border-bottom: 1px solid var(--gray-100);
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gray-600);
}

.pricing-features li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 600;
}

.pricing-features li.missing {
  color: var(--gray-400);
}

.pricing-features li.missing::before {
  content: '—';
  color: var(--gray-300);
}

.pricing-card .btn {
  width: 100%;
  margin-top: 16px;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--gray-800);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  font-size: 1.5rem;
  transition: var(--transition);
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 24px;
  color: var(--gray-500);
  line-height: 1.7;
}

/* Integration Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
}

.integration-category h4 {
  margin-bottom: 16px;
  color: var(--primary);
}

.integration-list {
  list-style: none;
}

.integration-list li {
  padding: 8px 0;
  color: var(--gray-600);
  border-bottom: 1px solid var(--gray-100);
}

/* CTA Section */
.cta-section {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
  text-align: center;
  padding: 80px 24px;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.cta-section .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-section .btn:hover {
  background: var(--gray-100);
  transform: translateY(-2px);
}

/* Contact Form */
.contact-form {
  max-width: 640px;
  margin: 0 auto;
  background: var(--white);
  padding: 48px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
}

.form-group {
  margin-bottom: 24px;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 8px;
  color: var(--gray-700);
}

.form-group label .required {
  color: var(--accent);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 14px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  font-size: 1rem;
  font-family: inherit;
  transition: var(--transition);
  background: var(--white);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: var(--accent);
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-error {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 6px;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-success {
  text-align: center;
  padding: 48px;
}

.form-success-icon {
  width: 80px;
  height: 80px;
  background: #10B981;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  font-size: 2.5rem;
  color: var(--white);
}

.form-success h3 {
  margin-bottom: 12px;
}

.form-success p {
  color: var(--gray-500);
}

/* Office Locations */
.office-locations {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
  margin-top: 48px;
}

.office h4 {
  margin-bottom: 8px;
  color: var(--primary);
}

.office p {
  color: var(--gray-500);
  font-size: 0.95rem;
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
  max-width: 800px;
  margin: 0 auto;
}

.team-member {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-family: 'Space Grotesk', sans-serif;
  font-size: 2rem;
  font-weight: 700;
}

.team-member h4 {
  margin-bottom: 4px;
}

.team-member p {
  color: var(--gray-500);
  font-size: 0.95rem;
}

/* Mission */
.mission-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  color: var(--gray-600);
  line-height: 1.8;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 24px 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.95rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

.footer-col h5 {
  color: var(--white);
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a {
  color: var(--gray-400);
  font-size: 0.95rem;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  max-width: 1200px;
  margin: 48px auto 0;
  padding-top: 32px;
  border-top: 1px solid var(--gray-700);
  text-align: center;
  font-size: 0.875rem;
}

/* Feature Detail Section */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-detail.reverse {
  direction: rtl;
}

.feature-detail.reverse > * {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 20px;
}

.feature-detail-content p {
  color: var(--gray-500);
  margin-bottom: 24px;
  line-height: 1.8;
}

.feature-detail-content ul {
  list-style: none;
}

.feature-detail-content li {
  padding: 8px 0;
  padding-left: 24px;
  position: relative;
  color: var(--gray-600);
}

.feature-detail-content li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--primary);
  font-weight: 600;
}

.feature-detail-visual {
  background: linear-gradient(135deg, var(--gray-100), var(--gray-50));
  border-radius: var(--radius-lg);
  height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  color: var(--gray-300);
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links,
  .nav-cta {
    display: none;
  }

